module.exports = "<div class=\"bmb_multi-dot-paginator\">\n  <header class=\"bmb_multi-dot-paginator-header\">\n    <h2 class=\"bmb_multi-dot-paginator-title\">\n      {{ title() }}\n      @if (subtitle()) {\n        <h4 class=\"bmb_multi-dot-paginator-subtitle\">{{ subtitle() }}</h4>\n      }\n    </h2>\n  </header>\n  <section class=\"bmb_multi-dot-paginator-content\">\n    <div\n      class=\"bmb_multi-dot-paginator-content-list\"\n      [style]=\"\n        '--numberOfElements: ' +\n        numberOfElements.length +\n        '; --selected-child: ' +\n        selectedIndex +\n        ';'\n      \"\n    >\n      <ng-content />\n      <div class=\"bmb_multi-dot-paginator-return\">\n        <bmb-fab\n          icon=\"keyboard_return\"\n          size=\"large\"\n          type=\"normal\"\n          text=\"Regresar al inicio\"\n          [mitec]=\"true\"\n          (click)=\"selectItem(0)\"\n        />\n      </div>\n    </div>\n    <button\n      class=\"bmb_multi-dot-paginator-next\"\n      (click)=\"setNextItem()\"\n      title=\"Siguiente\"\n    >\n      Siguiente\n    </button>\n  </section>\n  <footer class=\"bmb_multi-dot-paginator-footer\">\n    <ul\n      class=\"bmb_multi-dot-paginator-list\"\n      [style]=\"'--selected-child: ' + selectedIndex + ';'\"\n    >\n      @if (numberOfElements.length > 0) {\n        <li class=\"bmb_multi-dot-paginator-list-item\">\n          <bmb-action-icon\n            [disabled]=\"selectedIndex === 0\"\n            [icon]=\"'chevron_left'\"\n            [iconSize]=\"24\"\n            (buttonClick)=\"prevItem()\"\n          ></bmb-action-icon>\n        </li>\n      }\n      @for (dot of numberOfElements; track $index) {\n        <li\n          class=\"bmb_multi-dot-paginator-list-item\"\n          [ngClass]=\"{\n            'bmb_multi-dot-paginator-list-item-active': selectedIndex === $index\n          }\"\n        >\n          <button\n            class=\"bmb_multi-dot-paginator-dot\"\n            (click)=\"selectItem($index)\"\n            [title]=\"$index\"\n            [ngClass]=\"{\n              'bmb_multi-dot-paginator-dot-active': selectedIndex === $index\n            }\"\n          ></button>\n        </li>\n      }\n      @if (numberOfElements.length > 0) {\n        <li class=\"bmb_multi-dot-paginator-list-item\">\n          <bmb-action-icon\n            [disabled]=\"selectedIndex === numberOfElements.length - 1\"\n            [icon]=\"'chevron_right'\"\n            [iconSize]=\"24\"\n            (buttonClick)=\"nextItem()\"\n          ></bmb-action-icon>\n        </li>\n      }\n    </ul>\n  </footer>\n</div>\n";

